import React, { useEffect, useState } from "react";
import axios from "axios";

const API_URL = "http://localhost:5000";

function UserDashboard() {
  const [positions, setPositions] = useState([]);
  const [history, setHistory] = useState([]);
  const [status, setStatus] = useState("loading");
  const [candidates, setCandidates] = useState([]);

  useEffect(() => {
    // Fetch available positions
    axios.get(`${API_URL}/positions`)
      .then(res => setPositions(res.data))
      .catch(err => console.error(err));

    // Fetch voting history
    axios.get(`${API_URL}/votes/history`)
      .then(res => setHistory(res.data))
      .catch(err => console.error(err));

    // Fetch election status
    axios.get(`${API_URL}/admin/status`)
      .then(res => setStatus(res.data.status))
      .catch(err => console.error(err));

    // Fetch candidates
    axios.get(`${API_URL}/candidates`)
      .then(res => setCandidates(res.data))
      .catch(err => console.error(err));
  }, []);

  return (
    <div style={{ padding: 20 }}>
      <h1>User Dashboard</h1>
      <p><strong>Election Status:</strong> {status}</p>

      <section>
        <h2>Available Positions</h2>
        <ul>
          {positions.map(p => <li key={p._id}>{p.name}</li>)}
        </ul>
      </section>

      <section>
        <h2>Voting History</h2>
        <ul>
          {history.length === 0 ? <li>No votes yet</li> :
            history.map(v => <li key={v._id}>{v.position}: {v.candidateName}</li>)}
        </ul>
      </section>

      <section>
        <h2>Candidate Summary</h2>
        <ul>
          {candidates.map(c => (
            <li key={c._id}>
              {c.firstName} {c.lastName} - {c.candidacy}
            </li>
          ))}
        </ul>
      </section>
    </div>
  );
}

export default UserDashboard;
